<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('pos.hold');$rows=db()->query('SELECT s.id,s.sale_no,s.sale_date,s.total_amount,s.notes,u.full_name cashier,c.name customer_name,(SELECT COUNT(*) FROM sale_items si WHERE si.sale_id=s.id) item_count FROM sales s INNER JOIN users u ON u.id=s.created_by LEFT JOIN customers c ON c.id=s.customer_id WHERE s.status="held" ORDER BY s.updated_at DESC')->fetchAll();$pageTitle='Held Sales';$pageStyles=['admin.css','commerce.css','pos.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('pos/index'))?>">← POS</a><h2>Held sales</h2><p>Resume carts that were paused without changing inventory.</p></div><a class="button button--primary" href="<?=e(app_url('pos/index'))?>">New sale</a></div><section class="held-sales-grid"><?php if(!$rows):?><div class="panel-card empty-state"><strong>No held sales</strong><span>Held carts will appear here.</span></div><?php else:foreach($rows as$r):?><article class="held-sale-card"><div class="held-sale-card__top"><div><span class="eyebrow">Held sale</span><h3><?=e($r['sale_no'])?></h3></div><strong><?=e(money($r['total_amount']))?></strong></div><dl><div><dt>Customer</dt><dd><?=e($r['customer_name']?:'Walk-in')?></dd></div><div><dt>Items</dt><dd><?=e((string)$r['item_count'])?></dd></div><div><dt>Cashier</dt><dd><?=e($r['cashier'])?></dd></div><div><dt>Updated</dt><dd><?=e(format_datetime($r['sale_date']))?></dd></div></dl><a class="button button--primary" href="<?=e(app_url('pos/index?held='.(int)$r['id']))?>">Resume sale</a></article><?php endforeach;endif;?></section></main></div><?php require BASE_PATH.'/includes/footer.php';?>
